export default JSON.parse("{\"workId\":\"xunzi\",\"chapter\":{\"id\":\"xunzi_ch-22\",\"workId\":\"xunzi\",\"order\":22,\"title\":\"正名\",\"difficulty\":4,\"estimatedMinutes\":12,\"passageIds\":[\"xunzi_ch-22_p-1\",\"xunzi_ch-22_p-2\",\"xunzi_ch-22_p-3\",\"xunzi_ch-22_p-4\",\"xunzi_ch-22_p-5\",\"xunzi_ch-22_p-6\",\"xunzi_ch-22_p-7\",\"xunzi_ch-22_p-8\",\"xunzi_ch-22_p-9\",\"xunzi_ch-22_p-10\",\"xunzi_ch-22_p-11\",\"xunzi_ch-22_p-12\",\"xunzi_ch-22_p-13\",\"xunzi_ch-22_p-14\",\"xunzi_ch-22_p-15\",\"xunzi_ch-22_p-16\",\"xunzi_ch-22_p-17\",\"xunzi_ch-22_p-18\",\"xunzi_ch-22_p-19\",\"xunzi_ch-22_p-20\"],\"tags\":[\"儒家\",\"性惡論\",\"禮樂\"]},\"passages\":[{\"id\":\"xunzi_ch-22_p-1\",\"chapterId\":\"xunzi_ch-22\",\"order\":1,\"canonicalText\":\"後王之成名：刑名從商，爵名從周，文名從禮，散名之加於萬物者，則從諸夏之成俗曲期，遠方異俗之鄉，則因之而為通。\",\"sentenceIds\":[\"xunzi_ch-22_p-1_s-1\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"後王的成名：刑名從商，爵名從周，文名從禮正義道義道品德修養規程，散名的加於萬物的人或事物，則從諸夏的成俗曲期，遠方異俗的鄉，則因的而且為通。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 1 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「後王之成名：刑名從商，爵名從周，文名從禮，散名之加於萬物者，則從諸夏之成俗曲期，遠方異俗之鄉，則因之而為通」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「後王之成名：刑名從商，爵名從周，文名從禮，散名之加於……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-2\",\"chapterId\":\"xunzi_ch-22\",\"order\":2,\"canonicalText\":\"散名之在人者：生之所以然者謂之性；性之和所生，精合感應，不事而自然謂之性。性之好、惡、喜、怒、哀、樂謂之情。情然而心為之擇謂之慮。心慮而能為之動謂之偽；慮積焉，能習焉，而後成謂之偽。正利而為謂之事。正義而為謂之行。所以知之在人者謂之知；知有所合謂之智。所以能之在人者謂之能；能有所合謂之能。性傷謂之病。節遇謂之命：是散名之在人者也，是後王之成名也。\",\"sentenceIds\":[\"xunzi_ch-22_p-2_s-1\",\"xunzi_ch-22_p-2_s-2\",\"xunzi_ch-22_p-2_s-3\",\"xunzi_ch-22_p-2_s-4\",\"xunzi_ch-22_p-2_s-5\",\"xunzi_ch-22_p-2_s-6\",\"xunzi_ch-22_p-2_s-7\",\"xunzi_ch-22_p-2_s-8\",\"xunzi_ch-22_p-2_s-9\",\"xunzi_ch-22_p-2_s-10\",\"xunzi_ch-22_p-2_s-11\",\"xunzi_ch-22_p-2_s-12\",\"xunzi_ch-22_p-2_s-13\",\"xunzi_ch-22_p-2_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"散名的在人的人或事物：生的所以然的人或事物謂的性；性的和所生，精合感應，不事而且自然謂的性。性的好、惡、喜、怒、哀、樂謂的情。情然而且心為的擇謂的慮。心慮而且能為的動謂的偽；慮積焉，能習焉，而且後成謂的偽。正利而且為謂的事。正正義道義而且為謂的行。所以知的在人的人或事物謂的知；知有所合謂的智。所以能的在人的人或事物謂的能；能有所合謂的能。性傷謂的病。節遇謂的命：是散名的在人的人或事物啊，是後王的成名啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 2 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「散名之在人者：生之所以然者謂之性」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「散名之在人者：生之所以然者謂之性；性之和所生，精合感……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-3\",\"chapterId\":\"xunzi_ch-22\",\"order\":3,\"canonicalText\":\"故王者之制名，名定而實辨，道行而志通，則慎率民而一焉。故析辭擅作名，以亂正名，使民疑惑，人多辨訟，則謂之大姦。其罪猶為符節度量之罪也。故其民莫敢託為奇辭以亂正名，故其民愨；愨則易使，易使則公。其民莫敢託為奇辭以亂正名，故壹於道法，而謹於循令矣。如是則其跡長矣。跡長功成，治之極也。是謹於守名約之功也。今聖王沒，名守慢，奇辭起，名實亂，是非之形不明，則雖守法之吏，誦數之儒，亦皆亂也。若有王者起，必將有循於舊名，有作於新名。然則所為有名，與所緣以同異，與制名之樞要，不可不察也。\",\"sentenceIds\":[\"xunzi_ch-22_p-3_s-1\",\"xunzi_ch-22_p-3_s-2\",\"xunzi_ch-22_p-3_s-3\",\"xunzi_ch-22_p-3_s-4\",\"xunzi_ch-22_p-3_s-5\",\"xunzi_ch-22_p-3_s-6\",\"xunzi_ch-22_p-3_s-7\",\"xunzi_ch-22_p-3_s-8\",\"xunzi_ch-22_p-3_s-9\",\"xunzi_ch-22_p-3_s-10\",\"xunzi_ch-22_p-3_s-11\",\"xunzi_ch-22_p-3_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以王的人或事物的制名，名定而且實辨，道行而且志通，則慎率民而且一焉。所以析辭擅作名，以亂正名，使民疑惑，人多辨訟，則謂的大姦。他的罪猶為符節度量的罪啊。所以他的民莫敢託為奇辭以亂正名，所以他的民愨；愨則易使，易使則公。他的民莫敢託為奇辭以亂正名，所以壹於道國家典章法度，而且謹於循令矣。如是則他的跡長矣。跡長功成，治的極啊。是謹於守名約的功啊。今聖王沒，名守慢，奇辭起，名實亂，是絕不是的形不明，則雖守國家典章法度的吏，誦數的儒，亦皆亂啊。若有王的人或事物起，必將有循於舊名，有作於新名。然則所為有名，與所緣以同異，與制名的樞要，不可不察啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 3 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故王者之制名，名定而實辨，道行而志通，則慎率民而一焉」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故王者之制名，名定而實辨，道行而志通，則慎率民而一焉……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-4\",\"chapterId\":\"xunzi_ch-22\",\"order\":4,\"canonicalText\":\"異形離心交喻，異物名實玄紐，貴賤不明，同異不別；如是，則志必有不喻之患，而事必有困廢之禍。故知者為之分別制名以指實，上以明貴賤，下以辨同異。貴賤明，同異別，如是則志無不喻之患，事無困廢之禍，此所為有名也。\",\"sentenceIds\":[\"xunzi_ch-22_p-4_s-1\",\"xunzi_ch-22_p-4_s-2\",\"xunzi_ch-22_p-4_s-3\",\"xunzi_ch-22_p-4_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"異形離心交喻，異物名實玄紐，貴賤不明，同異不別；如是，則志必有不喻的患，而且事必有困廢的禍。所以知的人或事物為的分別制名以指實，上以明貴賤，下以辨同異。貴賤明，同異別，如是則志無不喻的患，事無困廢的禍，此所為有名啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 4 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「異形離心交喻，異物名實玄紐，貴賤不明，同異不別」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「異形離心交喻，異物名實玄紐，貴賤不明，同異不別；如是……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-5\",\"chapterId\":\"xunzi_ch-22\",\"order\":5,\"canonicalText\":\"然則何緣而以同異？曰：緣天官。凡同類同情者，其天官之意物也同。故比方之疑似而通，是所以共其約名以相期也。形體、色理以目異；聲音清濁、調竽、奇聲以耳異；甘、苦、鹹、淡、辛、酸、奇味以口異；香、臭、芬、鬱、腥、臊、漏庮、奇臭以鼻異；疾、癢、凔、熱、滑、鈹、輕、重以形體異；說、故、喜、怒、哀、樂、愛、惡、欲以心異。心有徵知。徵知，則緣耳而知聲可也，緣目而知形可也。然而徵知必將待天官之當簿其類，然後可也。五官簿之而不知，心徵知而無說，則人莫不然謂之不知。此所緣而以同異也。\",\"sentenceIds\":[\"xunzi_ch-22_p-5_s-1\",\"xunzi_ch-22_p-5_s-2\",\"xunzi_ch-22_p-5_s-3\",\"xunzi_ch-22_p-5_s-4\",\"xunzi_ch-22_p-5_s-5\",\"xunzi_ch-22_p-5_s-6\",\"xunzi_ch-22_p-5_s-7\",\"xunzi_ch-22_p-5_s-8\",\"xunzi_ch-22_p-5_s-9\",\"xunzi_ch-22_p-5_s-10\",\"xunzi_ch-22_p-5_s-11\",\"xunzi_ch-22_p-5_s-12\",\"xunzi_ch-22_p-5_s-13\",\"xunzi_ch-22_p-5_s-14\",\"xunzi_ch-22_p-5_s-15\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"然則何緣而且以同異？說道：緣天官。凡同類同情的人或事物，他的天官的意物啊同。所以比方的疑似而且通，是所以共他的約名以相期啊。形體、色理以目異；聲音清濁、調竽、奇聲以耳異；甘、苦、鹹、淡、辛、酸、奇味以口異；香、臭、芬、鬱、腥、臊、漏庮、奇臭以鼻異；疾、癢、凔、熱、滑、鈹、輕、重以形體異；說、所以、喜、怒、哀、樂、愛、惡、欲以心異。心有徵知。徵知，則緣耳而且知聲可啊，緣目而且知形可啊。然而且徵知必將待天官的當簿他的類，然後可啊。五官簿的而且不知，心徵知而且無說，則人莫不然謂的不知。此所緣而且以同異啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 5 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「然則何緣而以同異」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「然則何緣而以同異？曰：緣天官。凡同類同情者，其天官之……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-6\",\"chapterId\":\"xunzi_ch-22\",\"order\":6,\"canonicalText\":\"然後隨而命之，同則同之，異則異之。單足以喻則單，單不足以喻則兼；單與兼無所相避則共；雖共不為害矣。知異實者之異名也，故使異實者莫不異名也，不可亂也，猶使同實者莫不同名也。\",\"sentenceIds\":[\"xunzi_ch-22_p-6_s-1\",\"xunzi_ch-22_p-6_s-2\",\"xunzi_ch-22_p-6_s-3\",\"xunzi_ch-22_p-6_s-4\",\"xunzi_ch-22_p-6_s-5\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"然後隨而且命的，同則同的，異則異的。單足以喻則單，單不足以喻則兼；單與兼無所相避則共；雖共不為害矣。知異實的人或事物的異名啊，所以使異實的人或事物莫不異名啊，不可亂啊，猶使同實的人或事物莫不同名啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 6 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「然後隨而命之，同則同之，異則異之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「然後隨而命之，同則同之，異則異之。單足以喻則單，單不……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-7\",\"chapterId\":\"xunzi_ch-22\",\"order\":7,\"canonicalText\":\"故萬物雖眾，有時而欲無舉之，故謂之物；物也者，大共名也。推而共之，共則有共，至於無共然後止。有時而欲徧舉之，故謂之鳥獸。鳥獸也者，大別名也。推而別之，別則有別，至於無別然後止。\",\"sentenceIds\":[\"xunzi_ch-22_p-7_s-1\",\"xunzi_ch-22_p-7_s-2\",\"xunzi_ch-22_p-7_s-3\",\"xunzi_ch-22_p-7_s-4\",\"xunzi_ch-22_p-7_s-5\",\"xunzi_ch-22_p-7_s-6\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以萬物雖眾，有時而且欲無舉的，所以謂的物；物啊的人或事物，大共名啊。推而且共的，共則有共，至於無共然後止。有時而且欲徧舉的，所以謂的鳥獸。鳥獸啊的人或事物，大別名啊。推而且別的，別則有別，至於無別然後止。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 7 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故萬物雖眾，有時而欲無舉之，故謂之物」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故萬物雖眾，有時而欲無舉之，故謂之物；物也者，大共名……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-8\",\"chapterId\":\"xunzi_ch-22\",\"order\":8,\"canonicalText\":\"名無固宜，約之以命，約定俗成謂之宜，異於約則謂之不宜。名無固實，約之以命實，約定俗成，謂之實名。名有固善，徑易而不拂，謂之善名。\",\"sentenceIds\":[\"xunzi_ch-22_p-8_s-1\",\"xunzi_ch-22_p-8_s-2\",\"xunzi_ch-22_p-8_s-3\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"名無固宜，約的以命，約定俗成謂的宜，異於約則謂的不宜。名無固實，約的以命實，約定俗成，謂的實名。名有固善，徑易而且不拂，謂的善名。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 8 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「名無固宜，約之以命，約定俗成謂之宜，異於約則謂之不宜」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「名無固宜，約之以命，約定俗成謂之宜，異於約則謂之不宜……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-9\",\"chapterId\":\"xunzi_ch-22\",\"order\":9,\"canonicalText\":\"物有同狀而異所者，有異狀而同所者，可別也。狀同而為異所者，雖可合，謂之二實。狀變而實無別而為異者，謂之化。有化而無別，謂之一實。此事之所以稽實定數也。此制名之樞要也。後王之成名，不可不察也。\",\"sentenceIds\":[\"xunzi_ch-22_p-9_s-1\",\"xunzi_ch-22_p-9_s-2\",\"xunzi_ch-22_p-9_s-3\",\"xunzi_ch-22_p-9_s-4\",\"xunzi_ch-22_p-9_s-5\",\"xunzi_ch-22_p-9_s-6\",\"xunzi_ch-22_p-9_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"物有同狀而且異所的人或事物，有異狀而且同所的人或事物，可別啊。狀同而且為異所的人或事物，雖可合，謂的二實。狀變而且實無別而且為異的人或事物，謂的化。有化而且無別，謂的一實。此事的所以稽實定數啊。此制名的樞要啊。後王的成名，不可不察啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 9 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「物有同狀而異所者，有異狀而同所者，可別也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「物有同狀而異所者，有異狀而同所者，可別也。狀同而為異……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-10\",\"chapterId\":\"xunzi_ch-22\",\"order\":10,\"canonicalText\":\"「見侮不辱」，「聖人不愛己」，「殺盜非殺人也」，此惑於用名以亂名者也。驗之所為有名，而觀其孰行，則能禁之矣。「山淵平」，「情慾寡」，「芻豢不加甘，大鐘不加樂」，此惑於用實，以亂名者也。驗之所緣無1以同異，而觀其孰調，則能禁之矣。「非而謁楹」，「有牛馬非馬也，」此惑於用名以亂實者也。驗之名約，以其所受，悖其所辭，則能禁之矣。\",\"sentenceIds\":[\"xunzi_ch-22_p-10_s-1\",\"xunzi_ch-22_p-10_s-2\",\"xunzi_ch-22_p-10_s-3\",\"xunzi_ch-22_p-10_s-4\",\"xunzi_ch-22_p-10_s-5\",\"xunzi_ch-22_p-10_s-6\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"見侮不辱，聖人不愛己，殺盜絕不是殺人啊，此惑於用名以亂名的人或事物啊。驗的所為有名，而且觀他的孰行，則能禁的矣。山淵平，情慾寡，芻豢不加甘，大鐘不加樂，此惑於用實，以亂名的人或事物啊。驗的所緣無1以同異，而且觀他的孰調，則能禁的矣。絕不是而且謁楹，有牛馬絕不是馬啊，此惑於用名以亂實的人或事物啊。驗的名約，以他的所受，悖他的所辭，則能禁的矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 10 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「「見侮不辱」，「聖人不愛己」，「殺盜非殺人也」，此惑於用名以亂名者也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「「見侮不辱」，「聖人不愛己」，「殺盜非殺人也」，此惑……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-11\",\"chapterId\":\"xunzi_ch-22\",\"order\":11,\"canonicalText\":\"凡邪說辟言之離正道而擅作者，無不類於三惑者矣。故明君知其分而不與辨也。夫民易一以道，而不可與共故。故明君臨之以勢，道之以道，申之以命，章之以論，禁之以刑。故其民之化道也如神，辨埶惡用矣哉！今聖王沒，天下亂，姦言起，君子無埶以臨之，無刑以禁之，故辨說也。實不喻，然後命，命不喻，然後期，期不喻，然後說，說不喻，然後辨。故期命辨說也者，用之大文也，而王業之始也。名聞而實喻，名之用也。累而成文，名之麗也。用麗俱得，謂之知名。名也者，所以期累實也。辭也者，兼異實之名以論一意也。辨說也者，不異實名以喻動靜之道也。期命也者，辨說之用也。辨說也者，心之象道也。心也者，道之工宰也。道也者，治之經理也。心合於道，說合於心，辭合於說。正名而期，質請而喻，辨異而不過，推類而不悖。聽則合文，辨則盡故。以正道而辨姦，猶引繩以持曲直。是故邪說不能亂，百家無所竄。有兼聽之明，而無矜奮之容；有兼覆之厚，而無伐德之色。說行則天下正，說不行則白道而冥窮。是聖人之辨說也。《詩》曰：「顒顒卬卬，如圭如璋，令聞令望，豈弟君子，四方為綱。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-22_p-11_s-1\",\"xunzi_ch-22_p-11_s-2\",\"xunzi_ch-22_p-11_s-3\",\"xunzi_ch-22_p-11_s-4\",\"xunzi_ch-22_p-11_s-5\",\"xunzi_ch-22_p-11_s-6\",\"xunzi_ch-22_p-11_s-7\",\"xunzi_ch-22_p-11_s-8\",\"xunzi_ch-22_p-11_s-9\",\"xunzi_ch-22_p-11_s-10\",\"xunzi_ch-22_p-11_s-11\",\"xunzi_ch-22_p-11_s-12\",\"xunzi_ch-22_p-11_s-13\",\"xunzi_ch-22_p-11_s-14\",\"xunzi_ch-22_p-11_s-15\",\"xunzi_ch-22_p-11_s-16\",\"xunzi_ch-22_p-11_s-17\",\"xunzi_ch-22_p-11_s-18\",\"xunzi_ch-22_p-11_s-19\",\"xunzi_ch-22_p-11_s-20\",\"xunzi_ch-22_p-11_s-21\",\"xunzi_ch-22_p-11_s-22\",\"xunzi_ch-22_p-11_s-23\",\"xunzi_ch-22_p-11_s-24\",\"xunzi_ch-22_p-11_s-25\",\"xunzi_ch-22_p-11_s-26\",\"xunzi_ch-22_p-11_s-27\",\"xunzi_ch-22_p-11_s-28\",\"xunzi_ch-22_p-11_s-29\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡邪說辟言的離正道而且擅作的人或事物，無不類於三惑的人或事物矣。所以明君知他的分而且不與辨啊。夫民易一以道，而且不可與共所以。所以明君臨的以勢，道的以道，申的以命，章的以論，禁的以刑。所以他的民的化道啊如神，辨埶惡用矣哉！今聖王沒，天下亂，姦言起，君子無埶以臨的，無刑以禁的，所以辨說啊。實不喻，然後命，命不喻，然後期，期不喻，然後說，說不喻，然後辨。所以期命辨說啊的人或事物，用的大文啊，而且王業的始啊。名聞而且實喻，名的用啊。累而且成文，名的麗啊。用麗俱得，謂的知名。名啊的人或事物，所以期累實啊。辭啊的人或事物，兼異實的名以論一意啊。辨說啊的人或事物，不異實名以喻動靜的道啊。期命啊的人或事物，辨說的用啊。辨說啊的人或事物，心的象道啊。心啊的人或事物，道的工宰啊。道啊的人或事物，治的經理啊。心合於道，說合於心，辭合於說。正名而且期，質請而且喻，辨異而且不過，推類而且不悖。聽則合文，辨則盡所以。以正道而且辨姦，猶引繩以持曲直。正因為如此邪說不能亂，百家無所竄。有兼聽的明，而且無矜奮的容；有兼覆的厚，而且無伐品德修養的色。說行則天下正，說不行則白道而且冥窮。是聖人的辨說啊。《詩》說道：顒顒卬卬，如圭如璋，令聞令望，豈弟君子，四方為綱。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 11 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡邪說辟言之離正道而擅作者，無不類於三惑者矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡邪說辟言之離正道而擅作者，無不類於三惑者矣。故明君……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-12\",\"chapterId\":\"xunzi_ch-22\",\"order\":12,\"canonicalText\":\"辭讓之節得矣，長少之理順矣；忌諱不稱，祅辭不出。以仁心說，以學心聽，以公心辨。不動乎眾人之非譽，不治觀者之耳目，不賂貴者之權埶，不利傳闢者之辭。故能處道而不貳，咄而不奪，利而不流，貴公正而賤鄙爭，是士君子之辨說也。《詩》曰：「長夜漫兮，永思騫兮，大古之不慢兮，禮義之不愆兮，何恤人之言兮！」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-22_p-12_s-1\",\"xunzi_ch-22_p-12_s-2\",\"xunzi_ch-22_p-12_s-3\",\"xunzi_ch-22_p-12_s-4\",\"xunzi_ch-22_p-12_s-5\",\"xunzi_ch-22_p-12_s-6\",\"xunzi_ch-22_p-12_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"辭讓的節得矣，長少的理順矣；忌諱不稱，祅辭不出。以仁愛慈悲之德心說，以學心聽，以公心辨。不動乎眾人的絕不是譽，不治觀的人或事物的耳目，不賂貴的人或事物的權埶，不利傳闢的人或事物的辭。所以能處道而且不貳，咄而且不奪，利而且不流，貴公正而且賤鄙爭，是士君子的辨說啊。《詩》說道：長夜漫兮，永思騫兮，大古的不慢兮，禮正義道義道品德修養規程正義道義的不愆兮，何恤人的言兮！此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 12 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「辭讓之節得矣，長少之理順矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「辭讓之節得矣，長少之理順矣；忌諱不稱，祅辭不出。以仁……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-13\",\"chapterId\":\"xunzi_ch-22\",\"order\":13,\"canonicalText\":\"君子之言，涉然而精，俛然而類，差差然而齊。彼正其名，當其辭，以務白其志義者也。彼名辭也者，志義之使也，足以相通，則舍之矣。苟之，姦也。故名足以指實，辭足以見極，則舍之矣。外是者，謂之訒，是君子之所棄，而愚者拾以為己寶。故愚者之言，芴然而粗，嘖然而不類，誻誻然而沸，彼誘其名，眩其辭，而無深於其志義者也。故窮藉而無極，甚勞而無功，貪而無名。故知者之言也，慮之易知也，行之易安也，持之易立也，成則必得其所好，而不遇其所惡焉。而愚者反是。《詩》曰：「為鬼為蜮，則不可得。有靦面目，視人罔極。作此好歌，以極反側。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-22_p-13_s-1\",\"xunzi_ch-22_p-13_s-2\",\"xunzi_ch-22_p-13_s-3\",\"xunzi_ch-22_p-13_s-4\",\"xunzi_ch-22_p-13_s-5\",\"xunzi_ch-22_p-13_s-6\",\"xunzi_ch-22_p-13_s-7\",\"xunzi_ch-22_p-13_s-8\",\"xunzi_ch-22_p-13_s-9\",\"xunzi_ch-22_p-13_s-10\",\"xunzi_ch-22_p-13_s-11\",\"xunzi_ch-22_p-13_s-12\",\"xunzi_ch-22_p-13_s-13\",\"xunzi_ch-22_p-13_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"君子的言，涉然而且精，俛然而且類，差差然而且齊。彼正他的名，當他的辭，以務白他的志正義道義的人或事物啊。彼名辭啊的人或事物，志正義道義的使啊，足以相通，則舍的矣。苟的，姦啊。所以名足以指實，辭足以見極，則舍的矣。外是的人或事物，謂的訒，是君子的所棄，而且愚的人或事物拾以為己寶。所以愚的人或事物的言，芴然而且粗，嘖然而且不類，誻誻然而且沸，彼誘他的名，眩他的辭，而且無深於他的志正義道義的人或事物啊。所以窮藉而且無極，甚勞而且無功，貪而且無名。所以知的人或事物的言啊，慮的易知啊，行的易安啊，持的易立啊，成則必得他的所好，而且不遇他的所惡焉。而且愚的人或事物反是。《詩》說道：為鬼為蜮，則不可得。有靦面目，視人罔極。作此好歌，以極反側。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 13 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「君子之言，涉然而精，俛然而類，差差然而齊」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「君子之言，涉然而精，俛然而類，差差然而齊。彼正其名，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-14\",\"chapterId\":\"xunzi_ch-22\",\"order\":14,\"canonicalText\":\"凡語治而待去欲者，無以道欲而困於有欲者也。凡語治而待寡慾者，無以節欲而困於多欲者也。有欲無欲，異類也，生死也，非治亂也。欲之多寡，異類也，情之數也，非治亂也。欲不待可得，而求者從所可。欲不待可得，所受乎天也；求者從所可，所受乎心也。所受乎天之一欲，制於所受乎心之多，固難類所受乎天也。人之所欲生甚矣，人之惡死甚矣；然而人有從生成死者，非不欲生而欲死也，不可以生而可以死也。故欲過之而動不及，心止之也。心之所可中理，則欲雖多，奚傷於治？欲不及而動過之，心使之也。心之所可失理，則欲雖寡，奚止於亂？故治亂在於心之所可，亡於情之所欲。不求之其所在，而求之其所亡，雖曰我得之，失之矣。\",\"sentenceIds\":[\"xunzi_ch-22_p-14_s-1\",\"xunzi_ch-22_p-14_s-2\",\"xunzi_ch-22_p-14_s-3\",\"xunzi_ch-22_p-14_s-4\",\"xunzi_ch-22_p-14_s-5\",\"xunzi_ch-22_p-14_s-6\",\"xunzi_ch-22_p-14_s-7\",\"xunzi_ch-22_p-14_s-8\",\"xunzi_ch-22_p-14_s-9\",\"xunzi_ch-22_p-14_s-10\",\"xunzi_ch-22_p-14_s-11\",\"xunzi_ch-22_p-14_s-12\",\"xunzi_ch-22_p-14_s-13\",\"xunzi_ch-22_p-14_s-14\",\"xunzi_ch-22_p-14_s-15\",\"xunzi_ch-22_p-14_s-16\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡語治而且待去欲的人或事物，無以道欲而且困於有欲的人或事物啊。凡語治而且待寡慾的人或事物，無以節欲而且困於多欲的人或事物啊。有欲無欲，異類啊，生死啊，絕不是治亂啊。欲的多寡，異類啊，情的數啊，絕不是治亂啊。欲不待可得，而且求的人或事物從所可。欲不待可得，所受乎天啊；求的人或事物從所可，所受乎心啊。所受乎天的一欲，制於所受乎心的多，固難類所受乎天啊。人的所欲生甚矣，人的惡死甚矣；然而且人有從生成死的人或事物，絕不是不欲生而且欲死啊，不可以生而且可以死啊。所以欲過的而且動不及，心止的啊。心的所可中理，則欲雖多，奚傷於治？欲不及而且動過的，心使的啊。心的所可失理，則欲雖寡，奚止於亂？所以治亂在於心的所可，亡於情的所欲。不求的他的所在，而且求的他的所亡，雖說道：我得的，失的矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 14 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡語治而待去欲者，無以道欲而困於有欲者也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡語治而待去欲者，無以道欲而困於有欲者也。凡語治而待……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-15\",\"chapterId\":\"xunzi_ch-22\",\"order\":15,\"canonicalText\":\"性者、天之就也；情者、性之質也；欲者、情之應也。以所欲為可得而求之，情之所必不免也。以為可而道之，知所必出也。故雖為守門，欲不可去，性之具也。雖為天子，欲不可盡。欲雖不可盡，可以近盡也。欲雖不可去，求可節也。所欲雖不可盡，求者猶近盡；欲雖不可去，所求不得，慮者欲節求也。道者、進則近盡，退則節求，天下莫之若也。\",\"sentenceIds\":[\"xunzi_ch-22_p-15_s-1\",\"xunzi_ch-22_p-15_s-2\",\"xunzi_ch-22_p-15_s-3\",\"xunzi_ch-22_p-15_s-4\",\"xunzi_ch-22_p-15_s-5\",\"xunzi_ch-22_p-15_s-6\",\"xunzi_ch-22_p-15_s-7\",\"xunzi_ch-22_p-15_s-8\",\"xunzi_ch-22_p-15_s-9\",\"xunzi_ch-22_p-15_s-10\",\"xunzi_ch-22_p-15_s-11\",\"xunzi_ch-22_p-15_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"性的人或事物、天的就啊；情的人或事物、性的質啊；欲的人或事物、情的應啊。以所欲為可得而且求的，情的所必不免啊。以為可而且道的，知所必出啊。所以雖為守門，欲不可去，性的具啊。雖為天子，欲不可盡。欲雖不可盡，可以近盡啊。欲雖不可去，求可節啊。所欲雖不可盡，求的人或事物猶近盡；欲雖不可去，所求不得，慮的人或事物慾節求啊。道的人或事物、進則近盡，退則節求，天下莫的若啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 15 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「性者、天之就也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「性者、天之就也；情者、性之質也；欲者、情之應也。以所……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-16\",\"chapterId\":\"xunzi_ch-22\",\"order\":16,\"canonicalText\":\"凡人莫不從其所可，而去其所不可。知道之莫之若也，而不從道者，無之有也。假之有人而欲南，無多；而惡北，無寡，豈為夫南之不可盡也，離南行而北走也哉！今人所欲，無多；所惡，無寡，豈為夫所欲之不可盡也，離得欲之道，而取所惡也哉！故可道而從之，奚以損之而亂？不可道而離之，奚以益之而治？故知者論道而已矣，小家珍說之所願者皆衰矣。\",\"sentenceIds\":[\"xunzi_ch-22_p-16_s-1\",\"xunzi_ch-22_p-16_s-2\",\"xunzi_ch-22_p-16_s-3\",\"xunzi_ch-22_p-16_s-4\",\"xunzi_ch-22_p-16_s-5\",\"xunzi_ch-22_p-16_s-6\",\"xunzi_ch-22_p-16_s-7\",\"xunzi_ch-22_p-16_s-8\",\"xunzi_ch-22_p-16_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡人莫不從他的所可，而且去他的所不可。知道的莫的若啊，而且不從道的人或事物，無的有啊。假的有人而且欲南，無多；而且惡北，無寡，豈為夫南的不可盡啊，離南行而且北走啊哉！今人所欲，無多；所惡，無寡，豈為夫所欲的不可盡啊，離得欲的道，而且取所惡啊哉！所以可道而且從的，奚以損的而且亂？不可道而且離的，奚以益的而且治？所以知的人或事物論道而且已矣，小家珍說的所願的人或事物皆衰矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 16 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡人莫不從其所可，而去其所不可」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡人莫不從其所可，而去其所不可。知道之莫之若也，而不……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-17\",\"chapterId\":\"xunzi_ch-22\",\"order\":17,\"canonicalText\":\"凡人之取也，所欲未嘗粹而來也；其去也，所惡未嘗粹而往也。故人無動而不可以不與權俱。衡不正，則重縣於仰，而人以為輕；輕縣於俛，而人以為重；此人所以惑於輕重也。權不正，則禍託於欲，而人以為福；福託於惡，而人以為禍；此亦人所以惑於禍福也。道者，古今之正權也；離道而內自擇，則不知禍福之所託。易者，以一易一，人曰：無得亦無喪也，以一易兩，人曰：無喪而有得也。以兩易一，人曰：無得而有喪也。計者取所多，謀者從所可。以兩易一，人莫之為，明其數也。從道而出，猶以一易兩也，奚喪！離道而內自擇，是猶以兩易一也，奚得！其累百年之慾，易一時之嫌，然且為之，不明其數也。\",\"sentenceIds\":[\"xunzi_ch-22_p-17_s-1\",\"xunzi_ch-22_p-17_s-2\",\"xunzi_ch-22_p-17_s-3\",\"xunzi_ch-22_p-17_s-4\",\"xunzi_ch-22_p-17_s-5\",\"xunzi_ch-22_p-17_s-6\",\"xunzi_ch-22_p-17_s-7\",\"xunzi_ch-22_p-17_s-8\",\"xunzi_ch-22_p-17_s-9\",\"xunzi_ch-22_p-17_s-10\",\"xunzi_ch-22_p-17_s-11\",\"xunzi_ch-22_p-17_s-12\",\"xunzi_ch-22_p-17_s-13\",\"xunzi_ch-22_p-17_s-14\",\"xunzi_ch-22_p-17_s-15\",\"xunzi_ch-22_p-17_s-16\",\"xunzi_ch-22_p-17_s-17\",\"xunzi_ch-22_p-17_s-18\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡人的取啊，所欲未嘗粹而且來啊；他的去啊，所惡未嘗粹而且往啊。所以人無動而且不可以不與權俱。衡不正，則重縣於仰，而且人以為輕；輕縣於俛，而且人以為重；此人所以惑於輕重啊。權不正，則禍託於欲，而且人以為福；福託於惡，而且人以為禍；此亦人所以惑於禍福啊。道的人或事物，古今的正權啊；離道而且內自擇，則不知禍福的所託。易的人或事物，以一易一，人說道：無得亦無喪啊，以一易兩，人說道：無喪而且有得啊。以兩易一，人說道：無得而且有喪啊。計的人或事物取所多，謀的人或事物從所可。以兩易一，人莫的為，明他的數啊。從道而且出，猶以一易兩啊，奚喪！離道而且內自擇，是猶以兩易一啊，奚得！他的累百年的慾，易一時的嫌，然且為的，不明他的數啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 17 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡人之取也，所欲未嘗粹而來也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡人之取也，所欲未嘗粹而來也；其去也，所惡未嘗粹而往……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-18\",\"chapterId\":\"xunzi_ch-22\",\"order\":18,\"canonicalText\":\"有嘗試深觀其隱而難者：志輕理而不重物者，無之有也；外重物而不內憂者，無之有也；行離理而不外危者，無之有也；外危而不內恐者，無之有也。心憂恐，則口銜芻豢而不知其味，耳聽鐘鼓而不知其聲，目視黼黻而不知其狀，輕煖平簟而體不知其安。故嚮萬物之美而不能嗛也。假而得間而嗛之，則不能離也。故嚮萬物之美而盛憂，兼萬物之美而盛害，如此者，其求物也，養生也？粥壽也？故欲養其欲而縱其情，欲養其性而危其形，欲養其樂而攻其心，欲養其名而亂其行，如此者，雖封侯稱君，其與夫盜無以異；乘軒戴絻，其與無足無以異。夫是之謂以己為物役矣。\",\"sentenceIds\":[\"xunzi_ch-22_p-18_s-1\",\"xunzi_ch-22_p-18_s-2\",\"xunzi_ch-22_p-18_s-3\",\"xunzi_ch-22_p-18_s-4\",\"xunzi_ch-22_p-18_s-5\",\"xunzi_ch-22_p-18_s-6\",\"xunzi_ch-22_p-18_s-7\",\"xunzi_ch-22_p-18_s-8\",\"xunzi_ch-22_p-18_s-9\",\"xunzi_ch-22_p-18_s-10\",\"xunzi_ch-22_p-18_s-11\",\"xunzi_ch-22_p-18_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"有嘗試深觀他的隱而且難的人或事物：志輕理而且不重物的人或事物，無的有啊；外重物而且不內憂的人或事物，無的有啊；行離理而且不外危的人或事物，無的有啊；外危而且不內恐的人或事物，無的有啊。心憂恐，則口銜芻豢而且不知他的味，耳聽鐘鼓而且不知他的聲，目視黼黻而且不知他的狀，輕煖平簟而且體不知他的安。所以嚮萬物的美而且不能嗛啊。假而且得間而且嗛的，則不能離啊。所以嚮萬物的美而且盛憂，兼萬物的美而且盛害，如此的人或事物，他的求物啊，養生啊？粥壽啊？所以欲養他的欲而且縱他的情，欲養他的性而且危他的形，欲養他的樂而且攻他的心，欲養他的名而且亂他的行，如此的人或事物，雖封侯稱君，他的與夫盜無以異；乘軒戴絻，他的與無足無以異。這就是儒家所稱的以己為物役矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 18 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「有嘗試深觀其隱而難者：志輕理而不重物者，無之有也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「有嘗試深觀其隱而難者：志輕理而不重物者，無之有也；外……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-19\",\"chapterId\":\"xunzi_ch-22\",\"order\":19,\"canonicalText\":\"心平愉，則色不及傭而可以養目，聲不及傭而可以養耳，蔬食菜羹而可以養口，麤布之衣，麤紃之履，而可以養體。局室、蘆簾、稿蓐、敝機筵，而可以養形。故雖無萬物之美而可以養樂，無埶列之位而可以養名。如是而加天下焉，其為天下多，其私樂少矣。夫是之謂重己役物。\",\"sentenceIds\":[\"xunzi_ch-22_p-19_s-1\",\"xunzi_ch-22_p-19_s-2\",\"xunzi_ch-22_p-19_s-3\",\"xunzi_ch-22_p-19_s-4\",\"xunzi_ch-22_p-19_s-5\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"心平愉，則色不及傭而且可以養目，聲不及傭而且可以養耳，蔬食菜羹而且可以養口，麤布的衣，麤紃的履，而且可以養體。局室、蘆簾、稿蓐、敝機筵，而且可以養形。所以雖無萬物的美而且可以養樂，無埶列的位而且可以養名。如是而且加天下焉，他的為天下多，他的私樂少矣。這就是儒家所稱的重己役物。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 19 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「心平愉，則色不及傭而可以養目，聲不及傭而可以養耳，蔬食菜羹而可以養口，麤布之衣，麤紃之履，而可以養體」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「心平愉，則色不及傭而可以養目，聲不及傭而可以養耳，蔬……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-22_p-20\",\"chapterId\":\"xunzi_ch-22\",\"order\":20,\"canonicalText\":\"無稽之言，不見之行，不聞之謀，君子慎之。\",\"sentenceIds\":[\"xunzi_ch-22_p-20_s-1\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"無稽的言，不見的行，不聞的謀，君子慎的。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈正名〉（第 20 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「無稽之言，不見之行，不聞之謀，君子慎之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「無稽之言，不見之行，不聞之謀，君子慎之。」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"xunzi_ch-22_p-1_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-1\",\"order\":1,\"canonicalText\":\"後王之成名：刑名從商，爵名從周，文名從禮，散名之加於萬物者，則從諸夏之成俗曲期，遠方異俗之鄉，則因之而為通。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":1,\"canonicalText\":\"散名之在人者：生之所以然者謂之性；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":2,\"canonicalText\":\"性之和所生，精合感應，不事而自然謂之性。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":3,\"canonicalText\":\"性之好、惡、喜、怒、哀、樂謂之情。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":4,\"canonicalText\":\"情然而心為之擇謂之慮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":5,\"canonicalText\":\"心慮而能為之動謂之偽；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":6,\"canonicalText\":\"慮積焉，能習焉，而後成謂之偽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":7,\"canonicalText\":\"正利而為謂之事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":8,\"canonicalText\":\"正義而為謂之行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":9,\"canonicalText\":\"所以知之在人者謂之知；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":10,\"canonicalText\":\"知有所合謂之智。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":11,\"canonicalText\":\"所以能之在人者謂之能；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":12,\"canonicalText\":\"能有所合謂之能。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":13,\"canonicalText\":\"性傷謂之病。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-2_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-2\",\"order\":14,\"canonicalText\":\"節遇謂之命：是散名之在人者也，是後王之成名也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":1,\"canonicalText\":\"故王者之制名，名定而實辨，道行而志通，則慎率民而一焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":2,\"canonicalText\":\"故析辭擅作名，以亂正名，使民疑惑，人多辨訟，則謂之大姦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":3,\"canonicalText\":\"其罪猶為符節度量之罪也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":4,\"canonicalText\":\"故其民莫敢託為奇辭以亂正名，故其民愨；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":5,\"canonicalText\":\"愨則易使，易使則公。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":6,\"canonicalText\":\"其民莫敢託為奇辭以亂正名，故壹於道法，而謹於循令矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":7,\"canonicalText\":\"如是則其跡長矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":8,\"canonicalText\":\"跡長功成，治之極也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":9,\"canonicalText\":\"是謹於守名約之功也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":10,\"canonicalText\":\"今聖王沒，名守慢，奇辭起，名實亂，是非之形不明，則雖守法之吏，誦數之儒，亦皆亂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":11,\"canonicalText\":\"若有王者起，必將有循於舊名，有作於新名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-3_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-3\",\"order\":12,\"canonicalText\":\"然則所為有名，與所緣以同異，與制名之樞要，不可不察也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-4_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-4\",\"order\":1,\"canonicalText\":\"異形離心交喻，異物名實玄紐，貴賤不明，同異不別；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-4_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-4\",\"order\":2,\"canonicalText\":\"如是，則志必有不喻之患，而事必有困廢之禍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-4_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-4\",\"order\":3,\"canonicalText\":\"故知者為之分別制名以指實，上以明貴賤，下以辨同異。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-4_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-4\",\"order\":4,\"canonicalText\":\"貴賤明，同異別，如是則志無不喻之患，事無困廢之禍，此所為有名也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":1,\"canonicalText\":\"然則何緣而以同異？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":2,\"canonicalText\":\"曰：緣天官。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":3,\"canonicalText\":\"凡同類同情者，其天官之意物也同。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":4,\"canonicalText\":\"故比方之疑似而通，是所以共其約名以相期也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":5,\"canonicalText\":\"形體、色理以目異；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":6,\"canonicalText\":\"聲音清濁、調竽、奇聲以耳異；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":7,\"canonicalText\":\"甘、苦、鹹、淡、辛、酸、奇味以口異；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":8,\"canonicalText\":\"香、臭、芬、鬱、腥、臊、漏庮、奇臭以鼻異；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":9,\"canonicalText\":\"疾、癢、凔、熱、滑、鈹、輕、重以形體異；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":10,\"canonicalText\":\"說、故、喜、怒、哀、樂、愛、惡、欲以心異。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":11,\"canonicalText\":\"心有徵知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":12,\"canonicalText\":\"徵知，則緣耳而知聲可也，緣目而知形可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":13,\"canonicalText\":\"然而徵知必將待天官之當簿其類，然後可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":14,\"canonicalText\":\"五官簿之而不知，心徵知而無說，則人莫不然謂之不知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-5_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-5\",\"order\":15,\"canonicalText\":\"此所緣而以同異也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-6_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-6\",\"order\":1,\"canonicalText\":\"然後隨而命之，同則同之，異則異之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-6_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-6\",\"order\":2,\"canonicalText\":\"單足以喻則單，單不足以喻則兼；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-6_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-6\",\"order\":3,\"canonicalText\":\"單與兼無所相避則共；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-6_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-6\",\"order\":4,\"canonicalText\":\"雖共不為害矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-6_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-6\",\"order\":5,\"canonicalText\":\"知異實者之異名也，故使異實者莫不異名也，不可亂也，猶使同實者莫不同名也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-7_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-7\",\"order\":1,\"canonicalText\":\"故萬物雖眾，有時而欲無舉之，故謂之物；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-7_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-7\",\"order\":2,\"canonicalText\":\"物也者，大共名也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-7_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-7\",\"order\":3,\"canonicalText\":\"推而共之，共則有共，至於無共然後止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-7_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-7\",\"order\":4,\"canonicalText\":\"有時而欲徧舉之，故謂之鳥獸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-7_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-7\",\"order\":5,\"canonicalText\":\"鳥獸也者，大別名也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-7_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-7\",\"order\":6,\"canonicalText\":\"推而別之，別則有別，至於無別然後止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-8_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-8\",\"order\":1,\"canonicalText\":\"名無固宜，約之以命，約定俗成謂之宜，異於約則謂之不宜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-8_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-8\",\"order\":2,\"canonicalText\":\"名無固實，約之以命實，約定俗成，謂之實名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-8_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-8\",\"order\":3,\"canonicalText\":\"名有固善，徑易而不拂，謂之善名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-9_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-9\",\"order\":1,\"canonicalText\":\"物有同狀而異所者，有異狀而同所者，可別也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-9_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-9\",\"order\":2,\"canonicalText\":\"狀同而為異所者，雖可合，謂之二實。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-9_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-9\",\"order\":3,\"canonicalText\":\"狀變而實無別而為異者，謂之化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-9_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-9\",\"order\":4,\"canonicalText\":\"有化而無別，謂之一實。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-9_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-9\",\"order\":5,\"canonicalText\":\"此事之所以稽實定數也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-9_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-9\",\"order\":6,\"canonicalText\":\"此制名之樞要也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-9_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-9\",\"order\":7,\"canonicalText\":\"後王之成名，不可不察也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-10_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-10\",\"order\":1,\"canonicalText\":\"「見侮不辱」，「聖人不愛己」，「殺盜非殺人也」，此惑於用名以亂名者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-10_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-10\",\"order\":2,\"canonicalText\":\"驗之所為有名，而觀其孰行，則能禁之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-10_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-10\",\"order\":3,\"canonicalText\":\"「山淵平」，「情慾寡」，「芻豢不加甘，大鐘不加樂」，此惑於用實，以亂名者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-10_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-10\",\"order\":4,\"canonicalText\":\"驗之所緣無1以同異，而觀其孰調，則能禁之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-10_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-10\",\"order\":5,\"canonicalText\":\"「非而謁楹」，「有牛馬非馬也，」此惑於用名以亂實者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-10_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-10\",\"order\":6,\"canonicalText\":\"驗之名約，以其所受，悖其所辭，則能禁之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":1,\"canonicalText\":\"凡邪說辟言之離正道而擅作者，無不類於三惑者矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":2,\"canonicalText\":\"故明君知其分而不與辨也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":3,\"canonicalText\":\"夫民易一以道，而不可與共故。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":4,\"canonicalText\":\"故明君臨之以勢，道之以道，申之以命，章之以論，禁之以刑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":5,\"canonicalText\":\"故其民之化道也如神，辨埶惡用矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":6,\"canonicalText\":\"今聖王沒，天下亂，姦言起，君子無埶以臨之，無刑以禁之，故辨說也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":7,\"canonicalText\":\"實不喻，然後命，命不喻，然後期，期不喻，然後說，說不喻，然後辨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":8,\"canonicalText\":\"故期命辨說也者，用之大文也，而王業之始也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":9,\"canonicalText\":\"名聞而實喻，名之用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":10,\"canonicalText\":\"累而成文，名之麗也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":11,\"canonicalText\":\"用麗俱得，謂之知名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":12,\"canonicalText\":\"名也者，所以期累實也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":13,\"canonicalText\":\"辭也者，兼異實之名以論一意也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":14,\"canonicalText\":\"辨說也者，不異實名以喻動靜之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":15,\"canonicalText\":\"期命也者，辨說之用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":16,\"canonicalText\":\"辨說也者，心之象道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":17,\"canonicalText\":\"心也者，道之工宰也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":18,\"canonicalText\":\"道也者，治之經理也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":19,\"canonicalText\":\"心合於道，說合於心，辭合於說。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":20,\"canonicalText\":\"正名而期，質請而喻，辨異而不過，推類而不悖。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":21,\"canonicalText\":\"聽則合文，辨則盡故。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":22,\"canonicalText\":\"以正道而辨姦，猶引繩以持曲直。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":23,\"canonicalText\":\"是故邪說不能亂，百家無所竄。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":24,\"canonicalText\":\"有兼聽之明，而無矜奮之容；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":25,\"canonicalText\":\"有兼覆之厚，而無伐德之色。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-26\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":26,\"canonicalText\":\"說行則天下正，說不行則白道而冥窮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-27\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":27,\"canonicalText\":\"是聖人之辨說也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-28\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":28,\"canonicalText\":\"《詩》曰：「顒顒卬卬，如圭如璋，令聞令望，豈弟君子，四方為綱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-11_s-29\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-11\",\"order\":29,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-12_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-12\",\"order\":1,\"canonicalText\":\"辭讓之節得矣，長少之理順矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-12_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-12\",\"order\":2,\"canonicalText\":\"忌諱不稱，祅辭不出。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-12_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-12\",\"order\":3,\"canonicalText\":\"以仁心說，以學心聽，以公心辨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-12_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-12\",\"order\":4,\"canonicalText\":\"不動乎眾人之非譽，不治觀者之耳目，不賂貴者之權埶，不利傳闢者之辭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-12_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-12\",\"order\":5,\"canonicalText\":\"故能處道而不貳，咄而不奪，利而不流，貴公正而賤鄙爭，是士君子之辨說也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-12_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-12\",\"order\":6,\"canonicalText\":\"《詩》曰：「長夜漫兮，永思騫兮，大古之不慢兮，禮義之不愆兮，何恤人之言兮！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-12_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-12\",\"order\":7,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":1,\"canonicalText\":\"君子之言，涉然而精，俛然而類，差差然而齊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":2,\"canonicalText\":\"彼正其名，當其辭，以務白其志義者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":3,\"canonicalText\":\"彼名辭也者，志義之使也，足以相通，則舍之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":4,\"canonicalText\":\"苟之，姦也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":5,\"canonicalText\":\"故名足以指實，辭足以見極，則舍之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":6,\"canonicalText\":\"外是者，謂之訒，是君子之所棄，而愚者拾以為己寶。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":7,\"canonicalText\":\"故愚者之言，芴然而粗，嘖然而不類，誻誻然而沸，彼誘其名，眩其辭，而無深於其志義者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":8,\"canonicalText\":\"故窮藉而無極，甚勞而無功，貪而無名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":9,\"canonicalText\":\"故知者之言也，慮之易知也，行之易安也，持之易立也，成則必得其所好，而不遇其所惡焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":10,\"canonicalText\":\"而愚者反是。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":11,\"canonicalText\":\"《詩》曰：「為鬼為蜮，則不可得。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":12,\"canonicalText\":\"有靦面目，視人罔極。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":13,\"canonicalText\":\"作此好歌，以極反側。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-13_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-13\",\"order\":14,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":1,\"canonicalText\":\"凡語治而待去欲者，無以道欲而困於有欲者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":2,\"canonicalText\":\"凡語治而待寡慾者，無以節欲而困於多欲者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":3,\"canonicalText\":\"有欲無欲，異類也，生死也，非治亂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":4,\"canonicalText\":\"欲之多寡，異類也，情之數也，非治亂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":5,\"canonicalText\":\"欲不待可得，而求者從所可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":6,\"canonicalText\":\"欲不待可得，所受乎天也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":7,\"canonicalText\":\"求者從所可，所受乎心也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":8,\"canonicalText\":\"所受乎天之一欲，制於所受乎心之多，固難類所受乎天也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":9,\"canonicalText\":\"人之所欲生甚矣，人之惡死甚矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":10,\"canonicalText\":\"然而人有從生成死者，非不欲生而欲死也，不可以生而可以死也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":11,\"canonicalText\":\"故欲過之而動不及，心止之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":12,\"canonicalText\":\"心之所可中理，則欲雖多，奚傷於治？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":13,\"canonicalText\":\"欲不及而動過之，心使之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":14,\"canonicalText\":\"心之所可失理，則欲雖寡，奚止於亂？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":15,\"canonicalText\":\"故治亂在於心之所可，亡於情之所欲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-14_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-14\",\"order\":16,\"canonicalText\":\"不求之其所在，而求之其所亡，雖曰我得之，失之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":1,\"canonicalText\":\"性者、天之就也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":2,\"canonicalText\":\"情者、性之質也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":3,\"canonicalText\":\"欲者、情之應也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":4,\"canonicalText\":\"以所欲為可得而求之，情之所必不免也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":5,\"canonicalText\":\"以為可而道之，知所必出也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":6,\"canonicalText\":\"故雖為守門，欲不可去，性之具也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":7,\"canonicalText\":\"雖為天子，欲不可盡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":8,\"canonicalText\":\"欲雖不可盡，可以近盡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":9,\"canonicalText\":\"欲雖不可去，求可節也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":10,\"canonicalText\":\"所欲雖不可盡，求者猶近盡；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":11,\"canonicalText\":\"欲雖不可去，所求不得，慮者欲節求也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-15_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-15\",\"order\":12,\"canonicalText\":\"道者、進則近盡，退則節求，天下莫之若也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-16_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-16\",\"order\":1,\"canonicalText\":\"凡人莫不從其所可，而去其所不可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-16_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-16\",\"order\":2,\"canonicalText\":\"知道之莫之若也，而不從道者，無之有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-16_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-16\",\"order\":3,\"canonicalText\":\"假之有人而欲南，無多；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-16_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-16\",\"order\":4,\"canonicalText\":\"而惡北，無寡，豈為夫南之不可盡也，離南行而北走也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-16_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-16\",\"order\":5,\"canonicalText\":\"今人所欲，無多；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-16_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-16\",\"order\":6,\"canonicalText\":\"所惡，無寡，豈為夫所欲之不可盡也，離得欲之道，而取所惡也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-16_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-16\",\"order\":7,\"canonicalText\":\"故可道而從之，奚以損之而亂？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-16_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-16\",\"order\":8,\"canonicalText\":\"不可道而離之，奚以益之而治？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-16_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-16\",\"order\":9,\"canonicalText\":\"故知者論道而已矣，小家珍說之所願者皆衰矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":1,\"canonicalText\":\"凡人之取也，所欲未嘗粹而來也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":2,\"canonicalText\":\"其去也，所惡未嘗粹而往也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":3,\"canonicalText\":\"故人無動而不可以不與權俱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":4,\"canonicalText\":\"衡不正，則重縣於仰，而人以為輕；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":5,\"canonicalText\":\"輕縣於俛，而人以為重；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":6,\"canonicalText\":\"此人所以惑於輕重也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":7,\"canonicalText\":\"權不正，則禍託於欲，而人以為福；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":8,\"canonicalText\":\"福託於惡，而人以為禍；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":9,\"canonicalText\":\"此亦人所以惑於禍福也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":10,\"canonicalText\":\"道者，古今之正權也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":11,\"canonicalText\":\"離道而內自擇，則不知禍福之所託。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":12,\"canonicalText\":\"易者，以一易一，人曰：無得亦無喪也，以一易兩，人曰：無喪而有得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":13,\"canonicalText\":\"以兩易一，人曰：無得而有喪也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":14,\"canonicalText\":\"計者取所多，謀者從所可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":15,\"canonicalText\":\"以兩易一，人莫之為，明其數也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":16,\"canonicalText\":\"從道而出，猶以一易兩也，奚喪！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":17,\"canonicalText\":\"離道而內自擇，是猶以兩易一也，奚得！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-17_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-17\",\"order\":18,\"canonicalText\":\"其累百年之慾，易一時之嫌，然且為之，不明其數也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":1,\"canonicalText\":\"有嘗試深觀其隱而難者：志輕理而不重物者，無之有也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":2,\"canonicalText\":\"外重物而不內憂者，無之有也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":3,\"canonicalText\":\"行離理而不外危者，無之有也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":4,\"canonicalText\":\"外危而不內恐者，無之有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":5,\"canonicalText\":\"心憂恐，則口銜芻豢而不知其味，耳聽鐘鼓而不知其聲，目視黼黻而不知其狀，輕煖平簟而體不知其安。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":6,\"canonicalText\":\"故嚮萬物之美而不能嗛也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":7,\"canonicalText\":\"假而得間而嗛之，則不能離也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":8,\"canonicalText\":\"故嚮萬物之美而盛憂，兼萬物之美而盛害，如此者，其求物也，養生也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":9,\"canonicalText\":\"粥壽也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":10,\"canonicalText\":\"故欲養其欲而縱其情，欲養其性而危其形，欲養其樂而攻其心，欲養其名而亂其行，如此者，雖封侯稱君，其與夫盜無以異；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":11,\"canonicalText\":\"乘軒戴絻，其與無足無以異。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-18_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-18\",\"order\":12,\"canonicalText\":\"夫是之謂以己為物役矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-19_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-19\",\"order\":1,\"canonicalText\":\"心平愉，則色不及傭而可以養目，聲不及傭而可以養耳，蔬食菜羹而可以養口，麤布之衣，麤紃之履，而可以養體。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-19_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-19\",\"order\":2,\"canonicalText\":\"局室、蘆簾、稿蓐、敝機筵，而可以養形。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-19_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-19\",\"order\":3,\"canonicalText\":\"故雖無萬物之美而可以養樂，無埶列之位而可以養名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-19_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-19\",\"order\":4,\"canonicalText\":\"如是而加天下焉，其為天下多，其私樂少矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-19_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-19\",\"order\":5,\"canonicalText\":\"夫是之謂重己役物。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-22_p-20_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-22\",\"passageId\":\"xunzi_ch-22_p-20\",\"order\":1,\"canonicalText\":\"無稽之言，不見之行，不聞之謀，君子慎之。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
